// Copyright (c) 2023 Symmetry Labs AG
// For more information, see https://docs.symm.io/legal-disclaimer/license
pragma solidity >=0.8.18;

/// @notice Record of a user's fast withdrawal via a trusted bridge
/// @dev Bridges allow users to bypass the deallocate cooldown. Flow:
///      1. User calls transferToBridge(amount, bridge) to request fast withdrawal
///      2. Bridge immediately sends funds to user's wallet outside SYMMIO
///      3. After cooldown passes, bridge calls withdrawReceivedBridgeValue() to claim funds
///      4. If user misconduct detected, transaction can be suspended/restored with reduced amount
struct BridgeTransaction {
	/// @notice Unique transaction identifier
	uint256 id;
	/// @notice Amount user transferred to the bridge
	uint256 amount;
	/// @notice User who requested the fast withdrawal
	address user;
	/// @notice Bridge contract that will receive the funds after cooldown
	address bridge;
	/// @notice When the transfer was initiated
	uint256 timestamp;
	/// @notice Current state of this withdrawal request
	BridgeTransactionStatus status;
}

/// @notice Lifecycle state of a bridge withdrawal request
/// @dev RECEIVED = User transferred funds, waiting for bridge to withdraw after cooldown
///      SUSPENDED = Frozen due to suspected user misconduct, bridge cannot withdraw
///      WITHDRAWN = Bridge has successfully withdrawn the funds from SYMMIO
enum BridgeTransactionStatus {
	RECEIVED,
	SUSPENDED,
	WITHDRAWN
}

/// @title BridgeStorage
/// @notice Fast withdrawal system allowing users to bypass deallocate cooldown
/// @dev Trusted bridges advance funds to users immediately, then claim from SYMMIO after
///      cooldown. The bridge bears the risk - if user misconduct is detected, the transaction
///      is suspended and the bridge may only recover a reduced amount after restoration.
library BridgeStorage {
	bytes32 internal constant BRIDGE_STORAGE_SLOT = keccak256("diamond.standard.storage.bridge");

	struct Layout {
		/// @notice Addresses authorized to operate as bridges
		/// @dev Only registered bridges can receive transfers via transferToBridge().
		///      Bridges must be highly trusted - they advance real funds to users.
		mapping(address => bool) bridges;
		/// @notice All bridge transactions by ID
		/// @dev Complete record of every fast withdrawal request including current status.
		mapping(uint256 => BridgeTransaction) bridgeTransactions;
		/// @notice Transaction IDs grouped by bridge
		/// @dev Maps bridge address => transaction IDs[]. Allows bridges to query
		///      all their pending withdrawals.
		mapping(address => uint256[]) bridgeTransactionIds;
		/// @notice Counter for generating transaction IDs
		/// @dev Incremented for each new transferToBridge() call.
		uint256 lastId;
		/// @notice Destination for funds from invalid/suspended transactions
		/// @dev When restoreBridgeTransaction() is called with validAmount < original amount,
		///      the difference (invalid portion) is sent here instead of back to the bridge.
		address invalidBridgedAmountsPool;
		/// @notice Additional metadata per transaction
		/// @dev Maps transactionId => arbitrary data. Reserved for future use.
		mapping(uint256 => bytes) bridgesData;
	}

	function layout() internal pure returns (Layout storage l) {
		bytes32 slot = BRIDGE_STORAGE_SLOT;
		assembly {
			l.slot := slot
		}
	}
}
"
    },
    "project/contracts/core/storages/ClearingHouseStorage.sol": {
      "content": "// SPDX-License-Identifier: SYMM-Core-Business-Source-License-1.1
// This contract is licensed under the SYMM Core Business Source License 1.1
// Copyright (c) 2023 Symmetry Labs AG
// For more information, see https://docs.symm.io/legal-disclaimer/license
pragma solidity >=0.8.18;

/// @notice Liquidation state for a cross-margin PartyB affecting all their counterparties
/// @dev Cross-margin (master account) PartyB liquidation is handled by the ClearingHouse
///      and affects all PartyAs at once.
///      inProgress prevents any actions with this PartyB during liquidation.
struct CrossLiquidationDetail {
	bytes liquidationId;
	int256 upnl;
	uint256 timestamp;
	uint256 deallocatedPool;
	bool inProgress;
}

/// @notice Takeover state for a PartyA liquidation being handled by the ClearingHouse
/// @dev When a PartyA liquidation gets stuck (e.g., due to Muon signature issues),
///      the ClearingHouse can take over and manually complete the liquidation.
///      inProgress prevents normal liquidation functions from running.
///      Structure mirrors CrossLiquidationDetail for consistency.
struct PartyATakeoverDetail {
	bytes liquidationId;
	uint256 deallocatedPool;
	bool inProgress;
}

/// @title ClearingHouseStorage
/// @notice Storage for ClearingHouse operations: cross PartyB liquidation and PartyA takeover
/// @dev Uses diamond storage pattern with a unique slot to avoid collisions.
library ClearingHouseStorage {
	bytes32 internal constant CLEARING_HOUSE_STORAGE_SLOT = keccak256("diamond.standard.storage.clearinghouse");

	struct Layout {
		/// @notice Liquidation state for cross PartyBs
		/// @dev Tracks cross-mode PartyB liquidation state (separate from AccountStorage.liquidationDetails which is for PartyA).
		mapping(address => CrossLiquidationDetail) crossLiquidationDetails;
		/// @notice Takeover state for PartyA liquidations
		/// @dev Maps partyA => PartyATakeoverDetail. When inProgress is true,
		///      the ClearingHouse has taken over the liquidation and normal
		///      liquidation functions are blocked.
		mapping(address => PartyATakeoverDetail) partyATakeoverDetails;
	}

	function layout() internal pure returns (Layout storage l) {
		bytes32 slot = CLEARING_HOUSE_STORAGE_SLOT;
		assembly {
			l.slot := slot
		}
	}
}
"
    },
    "project/contracts/core/storages/ExternalTransferStorage.sol": {
      "content": "// SPDX-License-Identifier: SYMM-Core-Business-Source-License-1.1
// This contract is licensed under the SYMM Core Business Source License 1.1
// Copyright (c) 2023 Symmetry Labs AG
// For more information, see https://docs.symm.io/legal-disclaimer/license
pragma solidity >=0.8.18;

/// @notice Status of an external transfer
/// @dev Tracks the lifecycle of external transfers to trusted targets (other Symmio diamonds or external contracts).
///      PENDING = initiated but not yet completed/canceled by provider
///      COMPLETED = provider accepted and deposited on target
///      CANCELED = user canceled
enum VirtualExternalTransferStatus {
	PENDING,
	COMPLETED,
	CANCELED
}

/// @notice Transfer request moving funds to a trusted target via a virtual provider
/// @dev Enables fund movement to any whitelisted target -- another Symmio diamond (e.g., perps and options)
///      or any trusted external contract. Uses virtual providers as intermediaries who credit the receiver
///      on the target. The provider must accept the transfer, or user can cancel.
struct VirtualExternalTransferRequest {
	uint256 id;
	address sender; // user in source contract
	address receiver; // recipient in target contract
	address source;
	address target;
	uint256 amount;
	uint256 timestamp;
	address provider; // virtual provider who handles the transfer
	VirtualExternalTransferStatus status;
}

/// @title ExternalTransferStorage
/// @notice Fund transfers to trusted external targets
/// @dev Uses diamond storage pattern with a unique slot to avoid collisions.
library ExternalTransferStorage {
	bytes32 internal constant EXTERNAL_TRANSFER_STORAGE_SLOT = keccak256("diamond.standard.storage.externaltransfer");

	struct Layout {
		/// @notice Counter for external transfer IDs
		/// @dev Auto-incremented when creating external transfers. Used as unique identifier
		///      for each external transfer request.
		uint256 lastExternalTransferId;
		/// @notice Stops cross protocol balance transfers when true
		/// @dev External transfers move funds between different protocols via
		///      relayer contracts. Pause this if the relayers are compromised.
		bool externalTransferPaused;
		/// @notice Relayer contracts authorized for external transfers to specific targets
		/// @dev Maps target address => authorized relayer. The relayer receives
		///      funds and deposits them on the target for the user.
		mapping(address => address) externalTransferTargetsRelayers;
		/// @notice External transfer request data by ID
		/// @dev Stores the full transfer request: sender, receiver, source/target contracts,
		///      amount, provider, and status. Provider must accept or user can cancel.
		mapping(uint256 => VirtualExternalTransferRequest) externalTransfers;
	}

	function layout() internal pure returns (Layout storage l) {
		bytes32 slot = EXTERNAL_TRANSFER_STORAGE_SLOT;
		assembly {
			l.slot := slot
		}
	}
}
"
    },
    "project/contracts/core/storages/FundingStorage.sol": {
      "content": "// SPDX-License-Identifier: SYMM-Core-Business-Source-License-1.1
// This contract is licensed under the SYMM Core Business Source License 1.1
// Copyright (c) 2023 Symmetry Labs AG
// For more information, see https://docs.symm.io/legal-disclaimer/license
pragma solidity >=0.8.18;

/// @notice Tracks funding rates and their weighted averages over time
/// @dev Funding rates are stored as price-adjusted values (rate * marketPrice)
///      to avoid repeated multiplication during fee calculations
struct FundingFee {
	// Current epoch's funding rates (price-adjusted: rate * marketPrice / 1e18)
	int256 currentLongRate; // Current rate for long positions
	int256 currentShortRate; // Current rate for short positions
	// Weighted average rates over all tracked epochs
	int256 accumulatedLongRate; // Historical weighted average for longs
	int256 accumulatedShortRate; // Historical weighted average for shorts
	// Epoch tracking
	uint256 lastUpdatedEpoch; // Epoch number when rates were last updated
	uint256 lastUpdatedTimeStamp;
	uint256 startEpochTimeStamp;
	uint256 startEpoch; // Epoch when funding tracking started
	uint256 epochDuration; // Duration of each funding period in seconds
	// Cumulative fee snapshots frozen at each epoch duration change
	int256 snapshotLongFee; // Accumulated long fee at last duration change
	int256 snapshotShortFee; // Accumulated short fee at last duration change
}

/// @title FundingStorage
/// @notice Funding rate configuration and system flags
/// @dev Uses diamond storage pattern with a unique slot to avoid collisions.
library FundingStorage {
	bytes32 internal constant FUNDING_STORAGE_SLOT = keccak256("diamond.standard.storage.funding");

	struct Layout {
		/// @notice Flag to disable the old per-quote funding iteration system
		/// @dev The old system required iterating through quotes to charge funding. When true,
		///      the new accumulative funding system is used exclusively. Set true once all
		///      solvers have migrated to the new system.
		bool legacyFundingDeprecated;
		/// @notice Enables the new accumulated funding rate system
		/// @dev The new system tracks weighted average funding rates at the symbol level.
		///      Both this and legacyFundingDeprecated control the funding transition.
		bool accumulatedFundingActivated;
		/// @notice Funding rate configuration per symbol per PartyB
		/// @dev Maps symbolId => partyB => FundingFee. Each hedger sets their own funding
		///      rates for each symbol. Contains current rates, accumulated averages,
		///      and epoch tracking for the weighted average funding system.
		mapping(uint256 => mapping(address => FundingFee)) fundingFees;
	}

	function layout() internal pure returns (Layout storage l) {
		bytes32 slot = FUNDING_STORAGE_SLOT;
		assembly {
			l.slot := slot
		}
	}
}
"
